PAGE = 64          # tiny page so the effect is visible
SLOT = 4           # bytes per slot entry

class Page:
    def __init__(self):
        self.data = bytearray(PAGE)
        self.slots = []       # slot -> [offset, length] or None
        self.end = PAGE       # records grow backward from the end

    def free(self):
        return self.end - SLOT * len(self.slots)

    def insert(self, text):
        b = text.encode()
        if self.free() < len(b) + SLOT:
            return None
        self.end -= len(b)
        self.data[self.end:self.end + len(b)] = b
        self.slots.append([self.end, len(b)])
        return len(self.slots) - 1       # RID = (page, slot)

    def get(self, s):
        off, n = self.slots[s]
        return self.data[off:off + n].decode()

    def delete(self, s):
        self.slots[s] = None             # only the slot is marked

    def compact(self):                   # slide records together
        new, end = bytearray(PAGE), PAGE
        for i, s in enumerate(self.slots):
            if s:
                end -= s[1]
                new[end:end + s[1]] = self.data[s[0]:s[0] + s[1]]
                self.slots[i] = [end, s[1]]   # only the offset changes
        self.data, self.end = new, end

p = Page()
a, b, c = p.insert("A" * 20), p.insert("B" * 20), p.insert("C" * 10)
print("slots", a, b, c, "free bytes", p.free())
p.delete(b)
print("after delete free bytes", p.free(), "- new 15-byte row:", p.insert("D" * 15))
p.compact()
print("after compact free bytes", p.free(), "- slot", c, "still reads", p.get(c))
print("new 15-byte row gets slot", p.insert("D" * 15))
